import React from 'react';
import { Cpu, Thermometer, Gauge, Activity, Clock, ChevronRight } from 'lucide-react';
import { useNavigate } from 'react-router-dom';

const FactoryDigitalTwinGrid = ({ machines = [] }) => {
  const navigate = useNavigate();

  // Fallback machine inventory if empty
  const displayMachines = machines.length > 0 ? machines : [
    { machineId: 'LOOM-101', name: 'Toyota Air Jet Alpha', currentStatus: 'RUNNING', healthScore: 96, temperature: 52.4, rpm: 1080, lastUpdated: '1s ago' },
    { machineId: 'LOOM-201', name: 'Dornier Heavy Shuttleless', currentStatus: 'MAINTENANCE', healthScore: 68, temperature: 76.8, rpm: 920, lastUpdated: 'Just now' },
    { machineId: 'LOOM-301', name: 'Itema A9500 Denim', currentStatus: 'RUNNING', healthScore: 98, temperature: 48.9, rpm: 1120, lastUpdated: '2s ago' },
    { machineId: 'LOOM-401', name: 'Tsudakoma Water Jet', currentStatus: 'IDLE', healthScore: 88, temperature: 58.1, rpm: 0, lastUpdated: '5s ago' },
    { machineId: 'LOOM-501', name: 'Picanol OmniPlus i', currentStatus: 'RUNNING', healthScore: 72, temperature: 64.2, rpm: 1040, lastUpdated: '1s ago' },
    { machineId: 'LOOM-601', name: 'Somet SuperExcel Rapier', currentStatus: 'RUNNING', healthScore: 94, temperature: 51.0, rpm: 1060, lastUpdated: '3s ago' },
  ];

  const getStatusColor = (status) => {
    const s = (status || '').toUpperCase();
    if (s === 'RUNNING') return { bg: 'rgba(16, 185, 129, 0.12)', border: '#10b981', dot: '#10b981', text: 'RUNNING' };
    if (s === 'IDLE') return { bg: 'rgba(245, 158, 11, 0.12)', border: '#f59e0b', dot: '#f59e0b', text: 'IDLE' };
    return { bg: 'rgba(244, 63, 94, 0.12)', border: '#f43f5e', dot: '#f43f5e', text: 'FAULT / MAINT' };
  };

  return (
    <div className="glass-card" style={{ padding: '1.5rem', marginBottom: '1.75rem' }}>
      {/* Header */}
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '1.25rem', flexWrap: 'wrap', gap: '0.5rem' }}>
        <div>
          <h2 style={{ fontSize: '1.15rem', fontWeight: '800', color: 'var(--text-primary)', display: 'flex', alignItems: 'center', gap: '0.5rem' }}>
            <Cpu size={20} style={{ color: 'var(--accent-primary)' }} /> Factory Digital Twin Live Layout
          </h2>
          <p style={{ fontSize: '0.78rem', color: 'var(--text-muted)', fontWeight: '600', marginTop: '2px' }}>
            Real-Time State Mirroring & Sensor Telemetry Matrix for Air Jet Weaving Looms
          </p>
        </div>

        <div style={{ display: 'flex', alignItems: 'center', gap: '1rem', fontSize: '0.78rem', fontWeight: '800' }}>
          <span style={{ display: 'flex', alignItems: 'center', gap: '0.35rem', color: '#10b981' }}>
            <span style={{ width: '8px', height: '8px', borderRadius: '50%', background: '#10b981' }} /> Running (Green)
          </span>
          <span style={{ display: 'flex', alignItems: 'center', gap: '0.35rem', color: '#f59e0b' }}>
            <span style={{ width: '8px', height: '8px', borderRadius: '50%', background: '#f59e0b' }} /> Idle (Yellow)
          </span>
          <span style={{ display: 'flex', alignItems: 'center', gap: '0.35rem', color: '#f43f5e' }}>
            <span style={{ width: '8px', height: '8px', borderRadius: '50%', background: '#f43f5e' }} /> Fault (Red)
          </span>
        </div>
      </div>

      {/* Grid of Machine Cards */}
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(290px, 1fr))', gap: '1.1rem' }}>
        {displayMachines.map((m) => {
          const st = getStatusColor(m.currentStatus);
          return (
            <div
              key={m.machineId || m.id}
              onClick={() => navigate('/digital-twin')}
              style={{
                background: 'var(--bg-primary)',
                borderRadius: 'var(--radius-sm)',
                padding: '1.1rem',
                border: `1px solid ${st.border}`,
                cursor: 'pointer',
                transition: 'all 0.2s ease',
                position: 'relative',
                boxShadow: '0 4px 12px rgba(0,0,0,0.03)',
              }}
              onMouseEnter={(e) => {
                e.currentTarget.style.transform = 'translateY(-3px)';
                e.currentTarget.style.boxShadow = '0 8px 24px rgba(8, 131, 149, 0.15)';
              }}
              onMouseLeave={(e) => {
                e.currentTarget.style.transform = 'none';
                e.currentTarget.style.boxShadow = '0 4px 12px rgba(0,0,0,0.03)';
              }}
            >
              {/* Card Top Header */}
              <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', marginBottom: '0.75rem' }}>
                <div>
                  <div style={{ fontSize: '0.76rem', color: 'var(--accent-primary)', fontWeight: '800', fontFamily: 'JetBrains Mono' }}>
                    {m.machineId}
                  </div>
                  <div style={{ fontSize: '0.95rem', fontWeight: '800', color: 'var(--text-primary)', marginTop: '2px' }}>
                    {m.name || m.assetName}
                  </div>
                </div>

                <div
                  style={{
                    background: st.bg,
                    color: st.dot,
                    padding: '0.2rem 0.6rem',
                    borderRadius: '12px',
                    fontSize: '0.68rem',
                    fontWeight: '800',
                    display: 'flex',
                    alignItems: 'center',
                    gap: '0.35rem',
                  }}
                >
                  <span
                    style={{
                      width: '6px',
                      height: '6px',
                      borderRadius: '50%',
                      background: st.dot,
                      boxShadow: `0 0 6px ${st.dot}`,
                    }}
                  />
                  {st.text}
                </div>
              </div>

              {/* Card Metrics Grid */}
              <div style={{ display: 'grid', gridTemplateColumns: 'repeat(3, 1fr)', gap: '0.5rem', margin: '0.75rem 0', padding: '0.65rem 0', borderTop: '1px border-subtle', borderBottom: '1px border-subtle' }}>
                <div>
                  <div style={{ fontSize: '0.68rem', color: 'var(--text-muted)', fontWeight: '700' }}>HEALTH</div>
                  <div style={{ fontSize: '0.9rem', fontWeight: '900', color: m.healthScore < 75 ? 'var(--status-maintenance)' : 'var(--accent-primary)' }}>
                    {m.healthScore || 96}%
                  </div>
                </div>

                <div>
                  <div style={{ fontSize: '0.68rem', color: 'var(--text-muted)', fontWeight: '700' }}>TEMP</div>
                  <div style={{ fontSize: '0.9rem', fontWeight: '900', color: (m.temperature || 52) > 70 ? 'var(--status-maintenance)' : 'var(--text-primary)' }}>
                    {m.temperature || 52.4}°C
                  </div>
                </div>

                <div>
                  <div style={{ fontSize: '0.68rem', color: 'var(--text-muted)', fontWeight: '700' }}>SPEED</div>
                  <div style={{ fontSize: '0.9rem', fontWeight: '900', color: 'var(--text-primary)' }}>
                    {m.rpm || 1080} <span style={{ fontSize: '0.68rem' }}>RPM</span>
                  </div>
                </div>
              </div>

              {/* Card Footer */}
              <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', fontSize: '0.72rem', color: 'var(--text-muted)' }}>
                <span style={{ display: 'flex', alignItems: 'center', gap: '0.25rem' }}>
                  <Clock size={11} /> {m.lastUpdated || '1s ago'}
                </span>
                <span style={{ color: 'var(--accent-primary)', fontWeight: '700', display: 'flex', alignItems: 'center' }}>
                  View Twin <ChevronRight size={12} />
                </span>
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
};

export default FactoryDigitalTwinGrid;
